// Preserve editable inputs on 422; on 409 the current database revision is shown.
$editable=static function(string $action,array $row)use($invalidForm):array{
    if(($invalidForm['action'] ?? '')!==$action||($invalidForm['id'] ?? '')!==$row['id'])return $row;
    $fields=match($action){'location'=>['name','latitude','longitude','timezone'],'station'=>['name','stream_url','country_code'],'instrument'=>['name','symbol','board','type']};
    foreach($fields as $field)if(is_string($invalidForm[$field] ?? null))$row[$field]=$invalidForm[$field];
    if($action==='station'){$row['genres_input']=is_string($invalidForm['genres'] ?? null)?$invalidForm['genres']:'';$url=parse_url($row['stream_url']);if($url && (isset($url['user'])||isset($url['pass'])))$row['stream_url']='';}
    if(in_array($action,['station','instrument'],true))$row['enabled']=($invalidForm['enabled'] ?? null)==='1';return $row;
};
$hidden=static function(string $action,?array $row=null,?string $identity=null)use($e,$csrf,$invalidForm,$fieldErrors,&$currentErrors,&$formKey):void{
    $id=$identity ?? ($row['id'] ?? '');$formKey=$action.'-'.($id===''?'new':$id);$currentErrors=($invalidForm['action'] ?? '')===$action&&($action==='watchlist'?($invalidForm['client_id'] ?? ''):($invalidForm['id'] ?? ''))===$id?$fieldErrors:[]; ?>
<input type="hidden" name="csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="action" value="<?= $e($action) ?>">
<?php if($row!==null): ?><input type="hidden" name="id" value="<?= $e($row['id'] ?? '') ?>"><input type="hidden" name="revision" value="<?= $e($row['revision'] ?? 1) ?>"><?php endif; ?>
<?php };
$fieldError=static function(string $name)use($e,&$currentErrors,&$formKey):void{if(isset($currentErrors[$name])){ ?><span class="field-error" id="error-<?= $e($formKey.'-'.$name) ?>"><?= $e($currentErrors[$name]) ?></span><?php }};
$errorAttributes=static function(string $name)use($e,&$currentErrors,&$formKey):void{if(isset($currentErrors[$name])){ ?> aria-invalid="true" aria-describedby="error-<?= $e($formKey.'-'.$name) ?>"<?php }};
$input=static function(string $name,string $label,mixed $value,string $type='text',bool $required=true)use($e,$fieldError,$errorAttributes):void{ ?><label><?= $e($label) ?> <input name="<?= $e($name) ?>" type="<?= $e($type) ?>" value="<?= $e($value) ?>" <?= $required?'required':'' ?><?php $errorAttributes($name); ?>><?php $fieldError($name); ?></label><?php };
