<?php if(isset($pairCode)): ?><section><h2>Одноразовый код</h2><p class="pair-code"><?= $e($pairCode) ?></p><p>Введите его на планшете в течение 10 минут. При обновлении страницы код исчезнет.</p></section><?php endif; ?>
<section><h2>Подключить планшет</h2><form method="post"><?php $hidden('pair_issue'); ?><label>Место <select name="location_id"><?php foreach($view['locations'] as $row): ?><option value="<?= $e($row['id']) ?>"><?= $e($row['name']) ?></option><?php endforeach; ?></select></label><label>Скопировать списки <select name="template_client_id"><option value="">Пустые списки</option><?php foreach($view['clients'] as $row): ?><option value="<?= $e($row['id']) ?>"><?= $e($row['name']) ?></option><?php endforeach; ?></select></label>
<?php foreach(MediaCentre\Security\ClientAccess::SCOPES as $scope): ?><label><input type="checkbox" name="scopes[]" value="<?= $e($scope) ?>" checked> <?= $e($scopeNames[$scope]) ?></label><?php endforeach; ?><button>Выдать код на 10 минут</button></form></section>
<?php foreach($view['clients'] as $client): ?><section><h2><?= $e($client['name']) ?></h2><p>Последняя связь: <?= $e($client['last_seen_at']) ?> · <?= $e($client['app_version']) ?> · <?= $client['revoked_at']?'Доступ отозван':(($client['paired'] ?? false)?'Доступ активен':'Шаблон, не сопряжён') ?></p>
<form method="post"><?php $hidden('client_title'); ?><input type="hidden" name="client_id" value="<?= $e($client['id']) ?>"><input type="hidden" name="revision" value="<?= $e($client['revision']) ?>"><label>Заголовок на планшете <input name="display_title" value="<?= $e($client['display_title'] ?? 'Мой дом') ?>" maxlength="24" required></label><button>Сохранить заголовок</button></form>
<form method="post"><?php $hidden('client_rights'); ?><input type="hidden" name="client_id" value="<?= $e($client['id']) ?>"><input type="hidden" name="revision" value="<?= $e($client['auth_revision']) ?>"><?php foreach(MediaCentre\Security\ClientAccess::SCOPES as $scope): ?><label><input type="checkbox" name="scopes[]" value="<?= $e($scope) ?>" <?= in_array($scope,json_decode($client['scopes'],true),true)?'checked':'' ?>> <?= $e($scopeNames[$scope]) ?></label><?php endforeach; ?><button>Сохранить права</button></form>
<?php if(!$client['revoked_at']): ?><form method="post"><?php $hidden('client_revoke'); ?><input type="hidden" name="client_id" value="<?= $e($client['id']) ?>"><input type="hidden" name="revision" value="<?= $e($client['auth_revision']) ?>"><button>Отозвать доступ</button></form><?php endif; ?></section><?php endforeach; endif; ?>
<?php if($section==='system'): ?><section><h2>Смена пароля</h2><form method="post"><?php $hidden('password'); ?><label>Текущий пароль <input name="old_password" type="password" autocomplete="current-password" required></label><label>Новый пароль (12–72 байта) <input name="new_password" type="password" autocomplete="new-password" required></label><label>Повторите пароль <input name="confirm_password" type="password" autocomplete="new-password" required></label><button>Сменить пароль и выйти из всех сессий</button></form></section><?php endif; ?>
</main></div></body></html>
